/**
 * Entries whose source text is composed at module load (enemy variants, set
 * pieces, Act II–IV stage names and beats, ultra variants). They are built from
 * the authored entries above with the same templates the content modules use.
 */
Object.assign(AUTHORED, R2_TEXT);

function derived(): Record<string, ContentText> {
  const out: Record<string, ContentText> = {};
  const pair = (key: string, fallback: string): ContentText => AUTHORED[key] ?? { en: fallback, id: fallback };

  // Enemy variants: world.ts spreads the base enemy and rewrites title/description.
  for (const base of Object.values(ENEMIES)) {
    if (base.archetype !== base.id || (base.tier ?? 1) !== 1) continue;
    const title = pair(`enemy.${base.id}.title`, base.title);
    const description = pair(`enemy.${base.id}.description`, base.description);
    const counter = pair(`enemy.${base.id}.counter`, base.counter);
    for (const v of VARIANTS) {
      const id = `${base.id}-${v.id}`;
      if (!ENEMIES[id]) continue;
      const tag = v.name.toUpperCase();
      if (title.en !== title.id) out[`enemy.${id}.title`] = { en: `${tag} · ${title.en}`, id: `${tag} · ${title.id}` };
      out[`enemy.${id}.description`] = {
        en: `${description.en} ${v.name} variant: the intent order shifts and the pressure mounts.`,
        id: `${description.id} Varian ${v.name}: urutan intent bergeser dan tekanan meningkat.`,
      };
      if (counter.en !== counter.id) out[`enemy.${id}.counter`] = counter;
    }
  }

  // Gear set pieces: "<power> · <hp> · <tempo>. <Set name>: <set description>".
  for (const g of GEAR) {
    const set = g.setId ? GEAR_SETS.find(s => s.id === g.setId) : undefined;
    if (!set) continue;
    const text = AUTHORED[`gearSet.${set.id}.description`];
    if (!text) continue;
    const stats = `${Math.round(g.power * 100)}% power · ${Math.round(g.hp * 100)}% HP · ${Math.round(g.tempo * 100)}% tempo. ${set.name}: `;
    out[`gear.${g.id}.description`] = { en: stats + text.en, id: stats + text.id };
  }

  // Act II–IV chapters: stage names are "<step> · <chapter name>", stage beats mirror `beats`.
  const steps: ContentText[] = [
    { en: 'Crossing', id: 'Penyeberangan' },
    { en: 'Pursuit', id: 'Pengejaran' },
    { en: 'Pressure', id: 'Tekanan' },
    { en: 'The threshold', id: 'Ambang batas' },
    { en: 'The reckoning', id: 'Saat penentuan' },
  ];
  for (const chapter of CAMPAIGN) {
    const beats = (chapter as { beats?: string[] }).beats;
    if (!beats) continue;
    chapter.stages.forEach((_, i) => {
      const step = steps[i];
      if (step) out[`campaign.${chapter.id}.stages.${i}.name`] = { en: `${step.en} · ${chapter.name}`, id: `${step.id} · ${chapter.name}` };
      const beat = AUTHORED[`campaign.${chapter.id}.beats.${i}`];
      if (beat) out[`campaign.${chapter.id}.stages.${i}.beat`] = beat;
    });
  }

  // Ultra signature / capstone variants extend the core gate and effect.
  for (const ultra of D8_ULTRAS) {
    const match = /^(.+)-ultra-(signature|capstone)$/.exec(ultra.id);
    if (!match) continue;
    const gate = AUTHORED[`d8ultra.${match[1]}-ultra-core.gate`];
    const effect = AUTHORED[`d8ultra.${match[1]}-ultra-core.effect`];
    if (!gate || !effect) continue;
    if (match[2] === 'signature') {
      out[`d8ultra.${ultra.id}.gate`] = { en: `${gate.en} + signature path`, id: `${gate.id} + jalur signature` };
      out[`d8ultra.${ultra.id}.effect`] = { en: `${effect.en} Signature variant with a longer cooldown.`, id: `${effect.id} Varian signature dengan cooldown lebih panjang.` };
    } else {
      out[`d8ultra.${ultra.id}.gate`] = { en: `${gate.en} + capstone`, id: `${gate.id} + capstone` };
      out[`d8ultra.${ultra.id}.effect`] = { en: `${effect.en} The capstone unlocks a final payoff without proc loops.`, id: `${effect.id} Capstone membuka payoff final tanpa loop proc.` };
    }
  }
  return out;
}

export const CONTENT_TEXT: Record<string, ContentText> = { ...AUTHORED, ...derived() };
